package com.gotrprogressbar;

/**
 * All Guardians of the Rift game identifiers and timing constants used by this plugin.
 *
 * RuneLite core has no named GOTR widget/varbit constants, so raw IDs are kept here in one
 * place. Every value is sourced from an accepted Plugin Hub plugin or the OSRS Wiki:
 * - DatBear/Guardians-of-the-Rift-Helper (GuardiansOfTheRiftHelperPlugin.java)
 * - hawolt/guardian-of-the-rift (StaticConstant.java, MinigameSlice.java)
 * - https://oldschool.runescape.wiki/w/Guardians_of_the_Rift
 */
public final class GotrConstants
{
	private GotrConstants()
	{
	}

	// Map region containing the GOTR game area (DatBear MINIGAME_MAIN_REGION / hawolt MINIGAME_REGION_ID)
	public static final int GOTR_REGION_ID = 14484;

	// Clientscript that refreshes the GOTR HUD; fires with the full minigame state as arguments
	// (hawolt MINIGAME_HUD_UPDATE_SCRIPT_ID)
	public static final int HUD_UPDATE_SCRIPT_ID = 5980;

	// Argument indexes of script 5980 (index 0 is the script id itself; hawolt MinigameSlice)
	public static final int ARG_ELEMENTAL_ENERGY = 1;
	public static final int ARG_CATALYTIC_ENERGY = 2;
	public static final int ARG_CURRENT_POWER = 3;
	public static final int ARG_MAX_POWER = 4;
	public static final int ARG_PORTAL_LOCATION = 5; // <= 0 when no portal is open
	public static final int ARG_ELEMENTAL_RUNE_INDEX = 6; // 0 = no altar open (mining phase / no game)
	public static final int ARG_CATALYTIC_RUNE_INDEX = 7;
	public static final int ARG_CURRENT_GUARDIANS = 8;
	public static final int ARG_MAX_GUARDIANS = 9;
	// During the mining phase this is an exact countdown (in ticks) until the altars open;
	// during crafting it is the current altar set's remaining time; between games it holds a
	// garbage negative value. Verified from live HUD logs 2026-07-13.
	public static final int ARG_GUARDIAN_TICKS = 10;
	public static final int ARG_PORTAL_TICKS = 11; // ticks until the open portal closes
	public static final int HUD_SCRIPT_ARG_COUNT = 12;

	// Live-verified round structure (HUD logs 2026-07-13): "The rift becomes active!" starts
	// the ROUND (mining phase). During mining, power sits at exactly max/10 with both rune
	// indexes 0 and ARG_GUARDIAN_TICKS counting down ~200 ticks (120 s) to the altars opening.
	// Crafting begins when a rune index goes above 0. Between rounds power is 0.
	public static final int MINING_PHASE_TICKS_NOMINAL = 200;
	// Sanity ceiling when interpreting ARG_GUARDIAN_TICKS as the mining countdown
	public static final int MINING_PHASE_TICKS_MAX = 250;

	// GOTR HUD parent widget, packed group 746 child 2; non-null only while inside the minigame
	// (DatBear PARENT_WIDGET_ID / hawolt MINIGAME_WIDGET_PARENT_ID)
	public static final int PARENT_WIDGET_ID = 48889858;

	// HUD power text widget, group 746 child 18 — fallback source for power if script args change
	// (hawolt MINIGAME_WIDGET_POWER_TEXT_WIDGET_ID)
	public static final int POWER_TEXT_WIDGET_ID = 48889874;

	// Banked, spendable reward points (DatBear onVarbitChanged; raw ints, no core constant exists)
	public static final int VARBIT_ELEMENTAL_POINTS = 13686;
	public static final int VARBIT_CATALYTIC_POINTS = 13685;

	// Inventory item container id (hawolt INVENTORY_CONTAINER_ID)
	public static final int INVENTORY_CONTAINER_ID = 93;

	// Exact game messages that anchor phase timing (DatBear onChatMessage, verbatim)
	public static final String CHAT_START_30S = "The rift will become active in 30 seconds.";
	public static final String CHAT_START_10S = "The rift will become active in 10 seconds.";
	public static final String CHAT_START_5S = "The rift will become active in 5 seconds.";
	public static final String CHAT_RIFT_ACTIVE = "The rift becomes active!";
	// Fired when the portal guardians extend the current game; DatBear pushes next start out 60s
	public static final String CHAT_PORTALS_EXTEND =
		"The Portal Guardians will keep their rifts open for another 30 seconds.";

	// Portal cadence. Cycle live-verified 2026-07-13: consecutive fresh spawns 141 s apart.
	// First-portal delay is wiki-sourced and still unmeasured from a full round — verify.
	// The exact countdown of an OPEN portal always comes from ARG_PORTAL_TICKS.
	public static final int FIRST_PORTAL_DELAY_SECONDS = 160;
	public static final int PORTAL_CYCLE_SECONDS = 140;
	public static final int PORTAL_ESTIMATE_TOLERANCE_SECONDS = 10;

	// A portal's full lifetime in ticks (live-verified 2026-07-13: two fresh spawns both
	// reported 44). Used to back-date the spawn when we first see a portal mid-life.
	public static final int PORTAL_LIFETIME_TICKS = 44;

	// One server tick in milliseconds
	public static final long GAME_TICK_MILLIS = 600L;

	// ---- scrolling game timeline (overlay geometry) ----

	// The locked mining window in seconds (200 ticks, live-verified)
	public static final long MINING_PHASE_SECONDS = 120L;

	// The bar shows this fixed span of game time (constant scale — never rescales). The
	// cursor moves left-to-right through a stationary timeline until it reaches the pin
	// fraction, then stays pinned while the timeline scrolls past it (camera with deadzone).
	// 0.40 * 300 s = 120 s: the cursor pins exactly when the mining phase ends, so mining
	// reads as a normal left-to-right progress bar and only crafting scrolls.
	public static final double TIMELINE_WINDOW_SECONDS = 300;
	public static final double TIMELINE_CURSOR_FRACTION = 0.40;

	// How far ahead future portal marks are generated, and a safety cap on their count
	public static final double TIMELINE_LOOKAHEAD_SECONDS = 300;
	public static final int MAX_TIMELINE_MARKS = 12;

	// How long the end-of-game summary stays on the bar before returning to the waiting state
	public static final long GAME_END_SUMMARY_SECONDS = 10L;

	// The chat anchors only give at most a 30 second heads-up; the extend message gives 60.
	// Cap for sanity-checking any future longer anchor sources found by spike S4.5.
	public static final long MAX_START_ETA_SECONDS = 130L;
}

package com.gotrprogressbar;

import com.gotrprogressbar.model.BarSize;
import com.gotrprogressbar.model.PointsMetric;
import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(GotrProgressBarConfig.GROUP)
public interface GotrProgressBarConfig extends Config
{
	String GROUP = "gotrprogressbar";

	@ConfigSection(
		name = "Goals",
		description = "Personal goals shown on the goal sub-bar (0 disables a goal)",
		position = 0
	)
	String goalsSection = "goals";

	@ConfigSection(
		name = "Display",
		description = "Bar size and optional elements",
		position = 1
	)
	String displaySection = "display";

	@Range(max = 999)
	@ConfigItem(
		keyName = "fragmentGoal",
		name = "Fragment goal",
		description = "Guardian fragments to mine during the mining phase; the sub-bar turns green once reached (0 = off)",
		position = 0,
		section = goalsSection
	)
	default int fragmentGoal()
	{
		return 120;
	}

	@ConfigItem(
		keyName = "pointsMetric",
		name = "Points metric",
		description = "What the crafting-phase goal counts: combined energy, one side only, or both sides split with their own goals",
		position = 1,
		section = goalsSection
	)
	default PointsMetric pointsMetric()
	{
		return PointsMetric.COMBINED;
	}

	@Range(max = 9999)
	@ConfigItem(
		keyName = "combinedPointsGoal",
		name = "Combined goal",
		description = "Total energy (elemental + catalytic) to earn each round; used by the Combined metric (0 = off)",
		position = 2,
		section = goalsSection
	)
	default int combinedPointsGoal()
	{
		return 300;
	}

	@Range(max = 9999)
	@ConfigItem(
		keyName = "elementalPointsGoal",
		name = "Elemental goal",
		description = "Elemental energy to earn each round; used by the Elemental metric and the elemental half of Both (split) (0 = off)",
		position = 3,
		section = goalsSection
	)
	default int elementalPointsGoal()
	{
		return 150;
	}

	@Range(max = 9999)
	@ConfigItem(
		keyName = "catalyticPointsGoal",
		name = "Catalytic goal",
		description = "Catalytic energy to earn each round; used by the Catalytic metric and the catalytic half of Both (split) (0 = off)",
		position = 4,
		section = goalsSection
	)
	default int catalyticPointsGoal()
	{
		return 150;
	}

	@ConfigItem(
		keyName = "barSize",
		name = "Size",
		description = "Preset overlay size (bar thickness and font)",
		position = 0,
		section = displaySection
	)
	default BarSize barSize()
	{
		return BarSize.SMALL;
	}

	@Range(min = 280, max = 700)
	@ConfigItem(
		keyName = "barWidth",
		name = "Bar width",
		description = "Width of the bar in pixels",
		position = 1,
		section = displaySection
	)
	default int barWidth()
	{
		return 420;
	}

	@Range(min = 15, max = 100)
	@ConfigItem(
		keyName = "opacity",
		name = "Opacity",
		description = "Overall opacity of the overlay, as a percentage (100 = fully opaque)",
		position = 2,
		section = displaySection
	)
	default int opacity()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "showGameTimer",
		name = "Show game timer",
		description = "Show the elapsed round clock in the top-right of the timeline",
		position = 3,
		section = displaySection
	)
	default boolean showGameTimer()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPortalMarkers",
		name = "Show portal markers",
		description = "Show past sections and estimated future windows for portals on the timeline (a live portal always shows)",
		position = 4,
		section = displaySection
	)
	default boolean showPortalMarkers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showBetweenRounds",
		name = "Show between-round countdown",
		description = "Show the 'Next game' countdown bar while no round is running",
		position = 5,
		section = displaySection
	)
	default boolean showBetweenRounds()
	{
		return true;
	}

	@ConfigItem(
		keyName = "belowGoalColor",
		name = "Below goal",
		description = "Sub-bar color while a goal has not been reached",
		position = 6,
		section = displaySection
	)
	default Color belowGoalColor()
	{
		return new Color(176, 71, 58);
	}

	@ConfigItem(
		keyName = "goalMetColor",
		name = "Goal met",
		description = "Sub-bar color once a goal has been reached",
		position = 7,
		section = displaySection
	)
	default Color goalMetColor()
	{
		return new Color(87, 166, 74);
	}
}

package com.gotrprogressbar;

import com.google.inject.Provides;
import com.gotrprogressbar.model.GotrSession;
import com.gotrprogressbar.model.HudSnapshot;
import com.gotrprogressbar.overlay.GotrProgressBarOverlay;
import java.time.Instant;
import java.util.Arrays;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "GOTR Progress Bar",
	description = "A single at-a-glance timeline bar for Guardians of the Rift: game phase, guardian power, portal timers and configurable fragment/energy goals",
	tags = {"minigame", "overlay", "runecraft", "gotr", "guardians", "rift", "timer", "progress"}
)
public class GotrProgressBarPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GotrProgressBarOverlay overlay;

	@Inject
	private GotrProgressBarConfig config;

	@Getter
	private final GotrSession session = new GotrSession();

	private boolean warnedBadScriptArgs;

	// Ticks the HUD widget must be continuously absent before we consider the player outside.
	// Covers loading screens and short transitions (e.g. entering an altar) without resetting.
	private static final int GATE_GRACE_TICKS = 8;
	private int gateMissedTicks;

	@Provides
	GotrProgressBarConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GotrProgressBarConfig.class);
	}

	@Override
	protected void startUp()
	{
		session.reset();
		pushGoals();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		session.reset();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (GotrProgressBarConfig.GROUP.equals(event.getGroup()))
		{
			pushGoals();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Gate on the GOTR HUD widget being present AND visible (see isHudPresent). The altars
		// are separate map regions but the HUD persists and stays shown inside them, so a
		// region check would wrongly drop the overlay while runecrafting. A short grace period
		// covers loading transitions.
		if (isHudPresent())
		{
			gateMissedTicks = 0;
			session.setInMinigame(true);
			session.tick(Instant.now());
		}
		else if (++gateMissedTicks >= GATE_GRACE_TICKS)
		{
			session.setInMinigame(false);
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != GotrConstants.HUD_UPDATE_SCRIPT_ID)
		{
			return;
		}
		Object[] args = event.getScriptEvent() != null
			? event.getScriptEvent().getArguments()
			: null;
		HudSnapshot snapshot = HudSnapshot.fromArgs(args);
		if (snapshot == null)
		{
			if (!warnedBadScriptArgs)
			{
				warnedBadScriptArgs = true;
				log.warn("Unexpected GOTR HUD script arguments; the game may have updated: {}",
					Arrays.toString(args));
			}
			return;
		}
		log.debug("{}", snapshot);
		session.onHudUpdate(snapshot, Instant.now());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE
			&& event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		session.onChatMessage(Text.removeTags(event.getMessage()), Instant.now());
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != GotrConstants.INVENTORY_CONTAINER_ID)
		{
			return;
		}
		ItemContainer inventory = event.getItemContainer();
		if (inventory == null)
		{
			return;
		}
		int fragments = 0;
		for (Item item : inventory.getItems())
		{
			if (item != null && item.getId() == ItemID.GOTR_GUARDIAN_FRAGMENT)
			{
				fragments += item.getQuantity();
			}
		}
		session.setFragmentCount(fragments);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN
			|| event.getGameState() == GameState.HOPPING)
		{
			session.reset();
		}
	}

	private boolean isHudPresent()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		// The GOTR HUD widget lingers (hidden) after you leave the minigame, so a plain
		// null check kept the overlay up in the bank / after teleporting away. Requiring it
		// to be visible closes the gate on leave while still covering the rune altars, where
		// the HUD is genuinely shown. The grace period in onGameTick debounces brief hides.
		Widget hud = client.getWidget(GotrConstants.PARENT_WIDGET_ID);
		return hud != null && !hud.isHidden();
	}

	private void pushGoals()
	{
		session.setGoals(
			config.fragmentGoal(),
			config.pointsMetric(),
			config.combinedPointsGoal(),
			config.elementalPointsGoal(),
			config.catalyticPointsGoal());
	}
}

package com.gotrprogressbar.model;

/**
 * Preset overlay sizes. Carries the pixel metrics for the bars and whether to use the larger
 * RuneScape font. Heights are kept at or above each font's glyph height so text never clips.
 */
public enum BarSize
{
	SMALL("Small", 13, 16, 2, 16, false),
	MEDIUM("Medium", 16, 20, 2, 20, true),
	LARGE("Large", 20, 26, 3, 26, true);

	private final String label;
	private final int captionRow;
	private final int barHeight;
	private final int subGap;
	private final int subHeight;
	private final boolean largeFont;

	BarSize(String label, int captionRow, int barHeight, int subGap, int subHeight,
		boolean largeFont)
	{
		this.label = label;
		this.captionRow = captionRow;
		this.barHeight = barHeight;
		this.subGap = subGap;
		this.subHeight = subHeight;
		this.largeFont = largeFont;
	}

	public int captionRow()
	{
		return captionRow;
	}

	public int barHeight()
	{
		return barHeight;
	}

	public int subGap()
	{
		return subGap;
	}

	public int subHeight()
	{
		return subHeight;
	}

	public boolean largeFont()
	{
		return largeFont;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.gotrprogressbar.model;

/**
 * Lifecycle of a Guardians of the Rift round as seen by the player.
 */
public enum GamePhase
{
	/** Not inside the GOTR area; the overlay renders nothing. */
	OUTSIDE,
	/**
	 * Inside the area between rounds (HUD power is 0). Shows a countdown to the next round
	 * once the chat announces it ("The rift will become active in 30/10/5 seconds.").
	 */
	WAITING_FOR_GAME,
	/**
	 * The round has started ("The rift becomes active!") but the altars have not opened yet.
	 * Power sits at exactly 10%; the HUD guardian-ticks arg counts down the ~120 s mining
	 * window exactly. (Live-verified 2026-07-13.)
	 */
	MINING_PHASE,
	/** Crafting phase: altars are open (rune index > 0); power climbs toward 100%. */
	RIFT_ACTIVE,
	/** The round just ended; the bar shows a short summary before returning to waiting. */
	GAME_END
}

package com.gotrprogressbar.model;

/**
 * Tri-state result of comparing a tracked value against a user-configured goal.
 */
public enum GoalState
{
	/** Goal is set to 0 (feature off) — render neutrally. */
	DISABLED,
	/** Value is below the goal. */
	BELOW,
	/** Value has reached or passed the goal. */
	MET;

	public static GoalState of(int value, int goal)
	{
		if (goal <= 0)
		{
			return DISABLED;
		}
		return value >= goal ? MET : BELOW;
	}
}

package com.gotrprogressbar.model;

import com.gotrprogressbar.GotrConstants;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/**
 * The plugin's game-state model: an explicit phase state machine plus the fixed-timeline math
 * (cursor position, live round-length estimate, portal marks). Driven only by plain inputs
 * (HUD snapshots, chat strings, instants) — it never touches the RuneLite {@code Client}, so
 * it is fully unit-testable without mocks.
 */
public class GotrSession
{
	private GamePhase phase = GamePhase.OUTSIDE;

	// Countdown to the next round starting ("The rift becomes active!"), anchored by chat
	private Instant startEta;
	private Instant startAnchoredAt;

	// Mining phase: exact end time derived from the HUD guardian-ticks countdown
	private Instant miningEndsAt;

	// Round start ("The rift becomes active!" = mining begins). Anchor of the whole timeline.
	private Instant riftActiveAt;

	private HudSnapshot lastSnapshot;
	private Instant lastSnapshotAt;
	private final PortalPrediction portalPrediction = new PortalPrediction();

	// When we started observing the crafting phase (mid-join fallback clock / liveness)
	private Instant craftingObservedAt;

	// Game end summary
	private Instant gameEndedAt;
	private boolean lastGameWon;
	private int finalElementalEnergy;
	private int finalCatalyticEnergy;

	// Player progress + user goals (0 = disabled), pushed from config by the plugin
	private int fragmentCount;
	private int fragmentGoal;
	private PointsMetric pointsMetric = PointsMetric.COMBINED;
	private int combinedPointsGoal;
	private int elementalPointsGoal;
	private int catalyticPointsGoal;

	// ---- inputs ------------------------------------------------------------------------

	/** Gate signal: whether the player is inside the GOTR area with the HUD present. */
	public void setInMinigame(boolean inMinigame)
	{
		if (!inMinigame)
		{
			if (phase != GamePhase.OUTSIDE)
			{
				resetGameState();
				phase = GamePhase.OUTSIDE;
			}
			return;
		}
		if (phase == GamePhase.OUTSIDE)
		{
			phase = GamePhase.WAITING_FOR_GAME;
		}
	}

	/** Feeds one firing of HUD script 5980. */
	public void onHudUpdate(HudSnapshot snapshot, Instant now)
	{
		if (phase == GamePhase.OUTSIDE || snapshot == null)
		{
			return;
		}

		boolean wasPortalOpen = lastSnapshot != null && lastSnapshot.isPortalOpen();
		lastSnapshot = snapshot;
		lastSnapshotAt = now;

		if (snapshot.isCrafting())
		{
			if (phase != GamePhase.RIFT_ACTIVE)
			{
				phase = GamePhase.RIFT_ACTIVE;
				miningEndsAt = null;
				craftingObservedAt = now;
				clearStartCountdown();
				// Joined mid-craft (riftActiveAt null): the round clock stays hidden and
				// portal marks anchor off the first observed spawn — which is immediate if
				// a portal is already open, thanks to spawn back-dating below. Until then
				// the overlay shows a "watching for portal" liveness state.
			}
			if (snapshot.isPortalOpen() && !wasPortalOpen)
			{
				// Back-date the spawn when we first see a portal mid-life (e.g. joined or
				// logged in while it was already open) so the cycle stays anchored to the
				// true spawn time. A fresh spawn reports the full lifetime, backdate ~0.
				Instant spawnAt = now;
				if (snapshot.portalTicks > 0
					&& snapshot.portalTicks <= GotrConstants.PORTAL_LIFETIME_TICKS)
				{
					spawnAt = now.minusMillis(
						(GotrConstants.PORTAL_LIFETIME_TICKS - snapshot.portalTicks)
							* GotrConstants.GAME_TICK_MILLIS);
				}
				portalPrediction.onPortalSpawn(spawnAt);
			}
			else if (!snapshot.isPortalOpen() && wasPortalOpen)
			{
				portalPrediction.onPortalDespawn(now);
			}
			return;
		}

		if (snapshot.isGameWon())
		{
			if (phase == GamePhase.RIFT_ACTIVE)
			{
				endGame(now, true, snapshot);
			}
			return;
		}

		if (snapshot.isMiningPhase())
		{
			// Exact countdown to the altars opening, straight from the HUD
			miningEndsAt = now.plusMillis(snapshot.guardianTicks * GotrConstants.GAME_TICK_MILLIS);
			if (phase != GamePhase.MINING_PHASE)
			{
				phase = GamePhase.MINING_PHASE;
				clearStartCountdown();
				if (riftActiveAt == null)
				{
					// Joined mid-mining. Mining is a known fixed length, and the HUD gives
					// the exact remaining, so the round start = miningEnds - MINING_LENGTH.
					// Clamp elapsed to >= 0 so a longer-than-nominal countdown can never place
					// the start in the future (which made the bar render backwards).
					long remainingMs = (long) snapshot.guardianTicks
						* GotrConstants.GAME_TICK_MILLIS;
					long elapsedMs = Math.max(0,
						GotrConstants.MINING_PHASE_SECONDS * 1000 - remainingMs);
					riftActiveAt = now.minusMillis(elapsedMs);
					portalPrediction.anchor(riftActiveAt);
				}
			}
			return;
		}

		// Idle (power zero): no round is running
		if (snapshot.isIdle())
		{
			if (phase == GamePhase.RIFT_ACTIVE)
			{
				endGame(now, false, snapshot);
			}
			else if (phase == GamePhase.MINING_PHASE)
			{
				phase = GamePhase.WAITING_FOR_GAME;
				resetRound();
			}
		}
	}

	/** Feeds a game chat message with formatting tags already removed. */
	public void onChatMessage(String message, Instant now)
	{
		if (phase == GamePhase.OUTSIDE || message == null)
		{
			return;
		}

		if (message.startsWith(GotrConstants.CHAT_RIFT_ACTIVE))
		{
			// Round start: the MINING phase begins (live-verified — the altars open ~2
			// minutes later; the HUD countdown takes over from the next snapshot)
			phase = GamePhase.MINING_PHASE;
			riftActiveAt = now;
			clearStartCountdown();
			if (miningEndsAt == null)
			{
				miningEndsAt = now.plusSeconds(GotrConstants.MINING_PHASE_SECONDS);
			}
			portalPrediction.anchor(now);
		}
		else if (message.startsWith(GotrConstants.CHAT_START_30S))
		{
			anchorStart(now, 30);
		}
		else if (message.startsWith(GotrConstants.CHAT_START_10S))
		{
			anchorStart(now, 10);
		}
		else if (message.startsWith(GotrConstants.CHAT_START_5S))
		{
			anchorStart(now, 5);
		}
		else if (message.startsWith(GotrConstants.CHAT_PORTALS_EXTEND))
		{
			// The current round got extended, pushing the next round's start out. Mirrors
			// DatBear's handling (next start ~60s away). Only meaningful between rounds.
			if (phase == GamePhase.WAITING_FOR_GAME || phase == GamePhase.GAME_END)
			{
				anchorStart(now, 60);
			}
		}
	}

	public void setFragmentCount(int fragmentCount)
	{
		this.fragmentCount = Math.max(0, fragmentCount);
	}

	public void setGoals(int fragmentGoal, PointsMetric pointsMetric,
		int combinedPointsGoal, int elementalPointsGoal, int catalyticPointsGoal)
	{
		this.fragmentGoal = fragmentGoal;
		this.pointsMetric = pointsMetric == null ? PointsMetric.COMBINED : pointsMetric;
		this.combinedPointsGoal = combinedPointsGoal;
		this.elementalPointsGoal = elementalPointsGoal;
		this.catalyticPointsGoal = catalyticPointsGoal;
	}

	/** Periodic housekeeping; call once per game tick. */
	public void tick(Instant now)
	{
		if (phase == GamePhase.GAME_END && gameEndedAt != null
			&& Duration.between(gameEndedAt, now).getSeconds() >= GotrConstants.GAME_END_SUMMARY_SECONDS)
		{
			phase = GamePhase.WAITING_FOR_GAME;
		}
		if (phase == GamePhase.WAITING_FOR_GAME && startEta != null
			&& now.isAfter(startEta.plusSeconds(10)))
		{
			// The countdown elapsed but we never saw the round start (missed message,
			// filtered chat, ...). Drop the stale countdown.
			clearStartCountdown();
		}
	}

	public void reset()
	{
		resetGameState();
		phase = GamePhase.OUTSIDE;
	}

	// ---- scrolling timeline --------------------------------------------------------------

	/**
	 * All portal marks for the timeline, in absolute time: solid ticks at actual spawn times,
	 * the live portal (if open), and fixed future windows projected from the last real spawn
	 * (or from the round start for the first portal). Future marks only move when a real
	 * spawn re-anchors them — never with the clock.
	 */
	public List<PortalMark> portalMarks(Instant now)
	{
		List<PortalMark> marks = new ArrayList<>();
		if (phase != GamePhase.MINING_PHASE && phase != GamePhase.RIFT_ACTIVE)
		{
			return marks;
		}

		long lifetimeMs = GotrConstants.PORTAL_LIFETIME_TICKS * GotrConstants.GAME_TICK_MILLIS;
		List<Instant> spawns = portalPrediction.getSpawnHistory();
		Instant lastSpawn = null;
		for (int i = 0; i < spawns.size(); i++)
		{
			lastSpawn = spawns.get(i);
			boolean isActive = portalPrediction.isPortalOpen() && i == spawns.size() - 1;
			if (isActive)
			{
				// Section ends when the portal actually closes: exact remaining from the HUD
				long remaining = portalSecondsRemaining(now).orElse(-1L);
				Instant end = remaining >= 0
					? now.plusSeconds(remaining)
					: lastSpawn.plusMillis(lifetimeMs);
				marks.add(new PortalMark(PortalMark.State.ACTIVE, lastSpawn, end, remaining));
			}
			else
			{
				marks.add(new PortalMark(PortalMark.State.PAST, lastSpawn,
					lastSpawn.plusMillis(lifetimeMs), -1));
			}
		}

		Instant next;
		if (lastSpawn != null)
		{
			next = lastSpawn.plusSeconds(GotrConstants.PORTAL_CYCLE_SECONDS);
		}
		else if (riftActiveAt != null)
		{
			next = riftActiveAt.plusSeconds(GotrConstants.FIRST_PORTAL_DELAY_SECONDS);
		}
		else
		{
			return marks;
		}

		Instant horizon = now.plusSeconds((long) GotrConstants.TIMELINE_LOOKAHEAD_SECONDS);
		while (!next.isAfter(horizon) && marks.size() < GotrConstants.MAX_TIMELINE_MARKS)
		{
			marks.add(new PortalMark(PortalMark.State.FUTURE, next,
				next.plusMillis(lifetimeMs), -1));
			next = next.plusSeconds(GotrConstants.PORTAL_CYCLE_SECONDS);
		}
		return marks;
	}

	/** Seconds until the next expected portal (first FUTURE mark), while a round runs. */
	public Optional<Long> secondsToNextPortal(Instant now)
	{
		for (PortalMark mark : portalMarks(now))
		{
			if (mark.state == PortalMark.State.FUTURE && mark.time.isAfter(now))
			{
				return Optional.of(Duration.between(now, mark.time).getSeconds());
			}
		}
		return Optional.empty();
	}

	// ---- outputs -----------------------------------------------------------------------

	public GamePhase getPhase()
	{
		return phase;
	}

	/** Seconds until the next round starts, when a chat countdown anchor is known. */
	public Optional<Long> secondsToGameStart(Instant now)
	{
		if (startEta == null)
		{
			return Optional.empty();
		}
		return Optional.of(Math.max(0, Duration.between(now, startEta).getSeconds()));
	}

	/** Fill fraction of the next-game bar: share of the anchored wait already elapsed. */
	public Optional<Double> waitingFillFraction(Instant now)
	{
		if (startEta == null || startAnchoredAt == null)
		{
			return Optional.empty();
		}
		long total = Duration.between(startAnchoredAt, startEta).toMillis();
		if (total <= 0)
		{
			return Optional.of(1.0);
		}
		long elapsed = Duration.between(startAnchoredAt, now).toMillis();
		return Optional.of(Math.min(1.0, Math.max(0.0, (double) elapsed / (double) total)));
	}

	/** Seconds until the altars open (mining phase ends), exact from the HUD countdown. */
	public Optional<Long> miningSecondsRemaining(Instant now)
	{
		if (miningEndsAt == null)
		{
			return Optional.empty();
		}
		return Optional.of(Math.max(0, Duration.between(now, miningEndsAt).getSeconds()));
	}

	/** Guardian power as a 0..1 fraction. Not displayed — feeds the estimate and win check. */
	public double powerFraction()
	{
		return lastSnapshot == null ? 0 : lastSnapshot.powerFraction();
	}

	/** Elapsed time since the round started. */
	public Optional<Duration> elapsedSinceRiftActive(Instant now)
	{
		if (riftActiveAt == null)
		{
			return Optional.empty();
		}
		return Optional.of(Duration.between(riftActiveAt, now));
	}

	/** How long we've been watching a crafting phase whose start we didn't see (mid-join). */
	public Optional<Duration> observedCraftingElapsed(Instant now)
	{
		if (craftingObservedAt == null)
		{
			return Optional.empty();
		}
		return Optional.of(Duration.between(craftingObservedAt, now));
	}

	public boolean isPortalOpen()
	{
		return lastSnapshot != null && lastSnapshot.isPortalOpen();
	}

	/** Seconds until the currently open portal closes, from HUD ticks. */
	public Optional<Long> portalSecondsRemaining(Instant now)
	{
		if (!isPortalOpen() || lastSnapshot.portalTicks < 0 || lastSnapshotAt == null)
		{
			return Optional.empty();
		}
		long remainingMs = lastSnapshot.portalTicks * GotrConstants.GAME_TICK_MILLIS
			- Duration.between(lastSnapshotAt, now).toMillis();
		return Optional.of(Math.max(0, remainingMs / 1000));
	}

	public Optional<Instant> getRiftActiveAt()
	{
		return Optional.ofNullable(riftActiveAt);
	}

	public int getFragmentCount()
	{
		return fragmentCount;
	}

	public int getFragmentGoal()
	{
		return fragmentGoal;
	}

	public GoalState fragmentGoalState()
	{
		return GoalState.of(fragmentCount, fragmentGoal);
	}

	public int getElementalEnergy()
	{
		return lastSnapshot == null ? 0 : lastSnapshot.elementalEnergy;
	}

	public int getCatalyticEnergy()
	{
		return lastSnapshot == null ? 0 : lastSnapshot.catalyticEnergy;
	}

	public PointsMetric getPointsMetric()
	{
		return pointsMetric;
	}

	/** The goal used by the active single-value metric (not meaningful for BOTH_SPLIT). */
	public int activePointsGoal()
	{
		switch (pointsMetric)
		{
			case ELEMENTAL:
				return elementalPointsGoal;
			case CATALYTIC:
				return catalyticPointsGoal;
			default:
				return combinedPointsGoal;
		}
	}

	public int getElementalPointsGoal()
	{
		return elementalPointsGoal;
	}

	public int getCatalyticPointsGoal()
	{
		return catalyticPointsGoal;
	}

	/** The tracked points value under the configured metric (not used for BOTH_SPLIT). */
	public int pointsValue()
	{
		switch (pointsMetric)
		{
			case ELEMENTAL:
				return getElementalEnergy();
			case CATALYTIC:
				return getCatalyticEnergy();
			default:
				return getElementalEnergy() + getCatalyticEnergy();
		}
	}

	public GoalState pointsGoalState()
	{
		return GoalState.of(pointsValue(), activePointsGoal());
	}

	/** BOTH_SPLIT: each side tracks its own goal value. */
	public GoalState splitElementalGoalState()
	{
		return GoalState.of(getElementalEnergy(), elementalPointsGoal);
	}

	public GoalState splitCatalyticGoalState()
	{
		return GoalState.of(getCatalyticEnergy(), catalyticPointsGoal);
	}

	/** Whether the crafting-phase goal sub-bar has anything to show under the active metric. */
	public boolean hasPointsGoal()
	{
		if (pointsMetric == PointsMetric.BOTH_SPLIT)
		{
			return elementalPointsGoal > 0 || catalyticPointsGoal > 0;
		}
		return activePointsGoal() > 0;
	}

	public boolean wasLastGameWon()
	{
		return lastGameWon;
	}

	public int getFinalElementalEnergy()
	{
		return finalElementalEnergy;
	}

	public int getFinalCatalyticEnergy()
	{
		return finalCatalyticEnergy;
	}

	// ---- internals ---------------------------------------------------------------------

	private void anchorStart(Instant now, int seconds)
	{
		// Chat countdown to the next round's start; shown during the waiting state.
		startEta = now.plusSeconds(seconds);
		if (startAnchoredAt == null)
		{
			startAnchoredAt = now;
		}
		if (phase == GamePhase.GAME_END)
		{
			phase = GamePhase.WAITING_FOR_GAME;
		}
	}

	private void endGame(Instant now, boolean won, HudSnapshot finalSnapshot)
	{
		phase = GamePhase.GAME_END;
		gameEndedAt = now;
		lastGameWon = won;
		finalElementalEnergy = finalSnapshot.elementalEnergy;
		finalCatalyticEnergy = finalSnapshot.catalyticEnergy;
		resetRound();
	}

	private void resetRound()
	{
		riftActiveAt = null;
		miningEndsAt = null;
		craftingObservedAt = null;
		portalPrediction.reset();
		clearStartCountdown();
	}

	private void clearStartCountdown()
	{
		startEta = null;
		startAnchoredAt = null;
	}

	private void resetGameState()
	{
		resetRound();
		lastSnapshot = null;
		lastSnapshotAt = null;
		gameEndedAt = null;
		fragmentCount = 0;
	}
}

package com.gotrprogressbar.model;

import com.gotrprogressbar.GotrConstants;

/**
 * Immutable parse of one firing of the GOTR HUD update script (5980).
 * Argument layout verified against hawolt/guardian-of-the-rift MinigameSlice.
 */
public final class HudSnapshot
{
	public final int elementalEnergy;
	public final int catalyticEnergy;
	public final int currentPower;
	public final int maxPower;
	public final int portalLocation;
	public final int elementalRuneIndex;
	public final int catalyticRuneIndex;
	public final int currentGuardians;
	public final int maxGuardians;
	public final int guardianTicks;
	public final int portalTicks;

	public HudSnapshot(int elementalEnergy, int catalyticEnergy, int currentPower, int maxPower,
		int portalLocation, int elementalRuneIndex, int catalyticRuneIndex,
		int currentGuardians, int maxGuardians, int guardianTicks, int portalTicks)
	{
		this.elementalEnergy = elementalEnergy;
		this.catalyticEnergy = catalyticEnergy;
		this.currentPower = currentPower;
		this.maxPower = maxPower;
		this.portalLocation = portalLocation;
		this.elementalRuneIndex = elementalRuneIndex;
		this.catalyticRuneIndex = catalyticRuneIndex;
		this.currentGuardians = currentGuardians;
		this.maxGuardians = maxGuardians;
		this.guardianTicks = guardianTicks;
		this.portalTicks = portalTicks;
	}

	/**
	 * Defensively parses the raw script arguments. Returns null when the layout does not match
	 * expectations (wrong length or non-integer values) so a game update can never crash us.
	 */
	public static HudSnapshot fromArgs(Object[] args)
	{
		if (args == null || args.length < GotrConstants.HUD_SCRIPT_ARG_COUNT)
		{
			return null;
		}
		int[] values = new int[GotrConstants.HUD_SCRIPT_ARG_COUNT];
		for (int i = 1; i < GotrConstants.HUD_SCRIPT_ARG_COUNT; i++)
		{
			if (!(args[i] instanceof Integer))
			{
				return null;
			}
			values[i] = (Integer) args[i];
		}
		return new HudSnapshot(
			values[GotrConstants.ARG_ELEMENTAL_ENERGY],
			values[GotrConstants.ARG_CATALYTIC_ENERGY],
			values[GotrConstants.ARG_CURRENT_POWER],
			values[GotrConstants.ARG_MAX_POWER],
			values[GotrConstants.ARG_PORTAL_LOCATION],
			values[GotrConstants.ARG_ELEMENTAL_RUNE_INDEX],
			values[GotrConstants.ARG_CATALYTIC_RUNE_INDEX],
			values[GotrConstants.ARG_CURRENT_GUARDIANS],
			values[GotrConstants.ARG_MAX_GUARDIANS],
			values[GotrConstants.ARG_GUARDIAN_TICKS],
			values[GotrConstants.ARG_PORTAL_TICKS]);
	}

	public boolean isPortalOpen()
	{
		return portalLocation > 0;
	}

	/**
	 * True during the crafting phase: at least one altar (portal guardian) is open.
	 * Live-verified: rune indexes are 0 throughout the mining phase and between games.
	 */
	public boolean isCrafting()
	{
		return maxPower > 0 && currentPower > 0 && currentPower < maxPower
			&& (elementalRuneIndex > 0 || catalyticRuneIndex > 0);
	}

	/**
	 * True during the mining phase at the start of a round: power parked at exactly max/10,
	 * no altars open, and the guardian-ticks arg counting down to the altars opening.
	 */
	public boolean isMiningPhase()
	{
		return maxPower > 0
			&& currentPower * 10 == maxPower
			&& elementalRuneIndex == 0 && catalyticRuneIndex == 0
			&& guardianTicks > 0
			&& guardianTicks <= GotrConstants.MINING_PHASE_TICKS_MAX;
	}

	/** True when the rift has been sealed (win condition). */
	public boolean isGameWon()
	{
		return maxPower > 0 && currentPower >= maxPower;
	}

	/** True between rounds: the HUD reports zero power. */
	public boolean isIdle()
	{
		return maxPower <= 0 || currentPower <= 0;
	}

	public double powerFraction()
	{
		if (maxPower <= 0)
		{
			return 0;
		}
		return Math.min(1.0, Math.max(0.0, (double) currentPower / (double) maxPower));
	}

	@Override
	public String toString()
	{
		return "HudSnapshot{energy=" + elementalEnergy + "E/" + catalyticEnergy + "C"
			+ ", power=" + currentPower + "/" + maxPower
			+ ", portalLoc=" + portalLocation + ", portalTicks=" + portalTicks
			+ ", guardians=" + currentGuardians + "/" + maxGuardians
			+ ", runeIdx=" + elementalRuneIndex + "/" + catalyticRuneIndex
			+ ", guardianTicks=" + guardianTicks + "}";
	}
}

package com.gotrprogressbar.model;

/**
 * What the crafting-phase goal sub-bar counts.
 */
public enum PointsMetric
{
	COMBINED("Combined"),
	ELEMENTAL("Elemental only"),
	CATALYTIC("Catalytic only"),
	BOTH_SPLIT("Both (split)");

	private final String label;

	PointsMetric(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.gotrprogressbar.model;

import java.time.Instant;

/**
 * One portal marker on the scrolling game timeline. Times are absolute instants: actual spawn
 * times for PAST/ACTIVE marks, and projected times (last real spawn + cycle) for FUTURE ones.
 * A future mark only re-anchors when a portal actually spawns.
 */
public final class PortalMark
{
	public enum State
	{
		/** Spawned earlier this round; solid tick at its actual time. */
		PAST,
		/** Open right now; bright marker with an exact despawn countdown. */
		ACTIVE,
		/** Expected later; hatched tolerance window at its estimated time. */
		FUTURE
	}

	public final State state;
	/** This mark's start: actual spawn time, or the projected spawn time for FUTURE. */
	public final Instant time;
	/**
	 * When the portal closes/closed: actual projected close for PAST/ACTIVE (spawn +
	 * lifetime, or now + exact remaining for ACTIVE). For FUTURE this is the projected
	 * close of the estimated spawn, drawn as part of the tolerance window.
	 */
	public final Instant endTime;
	/** Despawn countdown in seconds; only meaningful for {@link State#ACTIVE}, else -1. */
	public final long secondsRemaining;

	public PortalMark(State state, Instant time, Instant endTime, long secondsRemaining)
	{
		this.state = state;
		this.time = time;
		this.endTime = endTime;
		this.secondsRemaining = secondsRemaining;
	}
}

package com.gotrprogressbar.model;

import com.gotrprogressbar.GotrConstants;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/**
 * Estimates when the next portal will appear during an active game.
 *
 * Cadence (OSRS Wiki, spike S4.3 confirms in-client): the first portal appears roughly
 * {@link GotrConstants#FIRST_PORTAL_DELAY_SECONDS} after the rift becomes active, and each
 * subsequent portal roughly {@link GotrConstants#PORTAL_CYCLE_SECONDS} after the previous
 * spawn. Every observed spawn re-anchors the cycle, so drift self-corrects. The estimate is
 * a window (± tolerance), never an exact promise, and is suppressed while a portal is open.
 */
public class PortalPrediction
{
	/** An estimated [start, end] window for the next portal spawn. */
	public static final class Window
	{
		public final Instant start;
		public final Instant end;

		Window(Instant start, Instant end)
		{
			this.start = start;
			this.end = end;
		}
	}

	private Instant riftActiveAt;
	private Instant lastSpawnAt;
	private boolean portalOpen;
	private final List<Instant> spawnHistory = new ArrayList<>();

	/** Anchors the first-portal estimate to the moment the rift became active. */
	public void anchor(Instant riftActiveAt)
	{
		this.riftActiveAt = riftActiveAt;
		this.lastSpawnAt = null;
		this.portalOpen = false;
		this.spawnHistory.clear();
	}

	public void onPortalSpawn(Instant now)
	{
		portalOpen = true;
		lastSpawnAt = now;
		spawnHistory.add(now);
	}

	public void onPortalDespawn(Instant now)
	{
		portalOpen = false;
	}

	public boolean isPortalOpen()
	{
		return portalOpen;
	}

	/** Spawn instants observed this game, oldest first (for time-strip markers). */
	public List<Instant> getSpawnHistory()
	{
		return new ArrayList<>(spawnHistory);
	}

	/**
	 * The estimated window for the next portal, or empty when there is no anchor yet
	 * (e.g. joined mid-game before seeing a portal) or a portal is currently open.
	 */
	public Optional<Window> nextWindow(Instant now)
	{
		if (portalOpen)
		{
			return Optional.empty();
		}

		final Instant center;
		if (lastSpawnAt != null)
		{
			center = lastSpawnAt.plusSeconds(GotrConstants.PORTAL_CYCLE_SECONDS);
		}
		else if (riftActiveAt != null)
		{
			center = riftActiveAt.plusSeconds(GotrConstants.FIRST_PORTAL_DELAY_SECONDS);
		}
		else
		{
			return Optional.empty();
		}

		Instant end = center.plusSeconds(GotrConstants.PORTAL_ESTIMATE_TOLERANCE_SECONDS);
		if (end.isBefore(now))
		{
			// The estimate has fully elapsed without an observed spawn; stop showing a stale
			// window rather than inventing a new one from nothing.
			return Optional.empty();
		}
		return Optional.of(new Window(
			center.minusSeconds(GotrConstants.PORTAL_ESTIMATE_TOLERANCE_SECONDS), end));
	}

	/** Seconds from now until the center of the next estimated window, if any. */
	public Optional<Long> secondsToNextEstimate(Instant now)
	{
		return nextWindow(now).map(w ->
		{
			Instant center = w.start.plusSeconds(
				Duration.between(w.start, w.end).getSeconds() / 2);
			return Math.max(0, Duration.between(now, center).getSeconds());
		});
	}

	public void reset()
	{
		riftActiveAt = null;
		lastSpawnAt = null;
		portalOpen = false;
		spawnHistory.clear();
	}
}

package com.gotrprogressbar.overlay;

import com.gotrprogressbar.GotrConstants;
import com.gotrprogressbar.GotrProgressBarConfig;
import com.gotrprogressbar.GotrProgressBarPlugin;
import com.gotrprogressbar.model.BarSize;
import com.gotrprogressbar.model.GamePhase;
import com.gotrprogressbar.model.GoalState;
import com.gotrprogressbar.model.GotrSession;
import com.gotrprogressbar.model.PointsMetric;
import com.gotrprogressbar.model.PortalMark;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;

/**
 * The two bars, styled like standard RuneLite overlays: translucent warm-dark ground
 * (ComponentConstants standard background), thin bars, translucent fills, small shadowed text.
 *
 * Bar A (between rounds): a plain next-game countdown.
 * Bar B (in a round): a fixed-scale scrolling timeline — 300 s window, "now" cursor pinned at
 * 25%, everything drifts smoothly past it. Phase label and round clock sit in a slim caption
 * row above the bar so the bar itself stays clean for marks. A mid-joined game shows a pulsing
 * "watching for portal" state until the first observed spawn anchors the cycle.
 */
public class GotrProgressBarOverlay extends Overlay
{
	// Bar metrics for the current frame, set from the configured size at the top of render().
	private int captionRow;
	private int barHeight;
	private int subGap;
	private int subHeight;

	// Opaque so opacity=100 is truly solid; the slider (AlphaComposite) scales it down. The
	// RuneLite standard background is translucent, which is why full opacity was unreachable.
	private static final Color BACKGROUND = opaque(ComponentConstants.STANDARD_BACKGROUND_COLOR);
	private static final Color BORDER = new Color(0, 0, 0, 180);
	private static final Color TEXT = Color.WHITE;
	private static final Color TEXT_DIM = new Color(200, 193, 174);
	private static final Color TEXT_YELLOW = new Color(255, 233, 74);
	// Section colors (user-specified): mining light blue, crafting green,
	// portal guess window transparent light yellow, actual portal section yellow
	private static final Color MINE_DONE = new Color(120, 180, 220, 150);
	private static final Color MINE_TODO = new Color(120, 180, 220, 55);
	private static final Color TRAIL_FILL = new Color(64, 142, 72, 110);
	private static final Color PORTAL_ACTIVE = new Color(255, 215, 64, 190);
	private static final Color PORTAL_PAST = new Color(255, 215, 64, 110);
	private static final Color PORTAL_GUESS = new Color(255, 230, 120, 50);
	private static final Color PORTAL_GUESS_EDGE = new Color(255, 230, 120, 130);
	private static final Color PORTAL_TEXT = new Color(255, 224, 96);
	private static final Color WAIT_FILL = new Color(112, 132, 152, 110);
	private static final Color CURSOR_SHADOW = new Color(0, 0, 0, 140);

	private final GotrProgressBarPlugin plugin;
	private final GotrProgressBarConfig config;

	@Inject
	public GotrProgressBarOverlay(GotrProgressBarPlugin plugin, GotrProgressBarConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		GotrSession session = plugin.getSession();
		GamePhase phase = session.getPhase();
		if (phase == GamePhase.OUTSIDE)
		{
			return null;
		}
		if (phase == GamePhase.WAITING_FOR_GAME && !config.showBetweenRounds())
		{
			return null;
		}

		Instant now = Instant.now();
		int width = config.barWidth();

		BarSize size = config.barSize();
		captionRow = size.captionRow();
		barHeight = size.barHeight();
		subGap = size.subGap();
		subHeight = size.subHeight();
		g.setFont(size.largeFont()
			? FontManager.getRunescapeFont()
			: FontManager.getRunescapeSmallFont());

		// Apply the opacity slider once for the whole overlay; our per-element alpha then
		// composites on top of it. Restored before returning so we never leak the composite.
		Composite originalComposite = g.getComposite();
		float opacity = Math.min(1f, Math.max(0f, config.opacity() / 100f));
		if (opacity < 1f)
		{
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity));
		}
		try
		{
			if (phase == GamePhase.WAITING_FOR_GAME)
			{
				renderNextGameBar(g, session, now, width);
				return new Dimension(width, barHeight);
			}

			boolean sub = hasGoalSubBar(session, phase);
			renderTimeline(g, session, phase, now, width);
			if (sub)
			{
				renderGoalSubBar(g, session, phase, width, captionRow + barHeight + subGap);
			}
			return new Dimension(width,
				captionRow + barHeight + (sub ? subGap + subHeight : 0));
		}
		finally
		{
			g.setComposite(originalComposite);
		}
	}

	private static Color opaque(Color c)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), 255);
	}

	// ---- Bar A: next game ----------------------------------------------------------------

	private void renderNextGameBar(Graphics2D g, GotrSession session, Instant now, int width)
	{
		frame(g, 0, 0, width, barHeight);
		Optional<Double> fill = session.waitingFillFraction(now);
		fill.ifPresent(f ->
		{
			g.setColor(WAIT_FILL);
			g.fillRect(1, 1, (int) ((width - 2) * f), barHeight - 2);
		});

		int base = baseline(g, 0, barHeight);
		shadowText(g, "Next game", 6, base, fill.isPresent() ? TEXT : TEXT_DIM);
		FontMetrics fm = g.getFontMetrics();
		Optional<Long> toStart = session.secondsToGameStart(now);
		if (toStart.isPresent())
		{
			String right = mmss(toStart.get());
			shadowText(g, right, width - fm.stringWidth(right) - 6, base, TEXT_YELLOW);
		}
		else
		{
			shadowText(g, "waiting...", width - fm.stringWidth("waiting...") - 6, base,
				pulse(TEXT_DIM));
		}
	}

	// ---- Bar B: scrolling game timeline -----------------------------------------------------

	private void renderTimeline(Graphics2D g, GotrSession session, GamePhase phase,
		Instant now, int width)
	{
		int y = captionRow;
		int innerW = width - 2;
		int capBase = captionRow - 4;
		FontMetrics fm = g.getFontMetrics();
		frame(g, 0, y, width, barHeight);

		if (phase == GamePhase.GAME_END)
		{
			g.setColor(TRAIL_FILL);
			g.fillRect(1, y + 1, innerW, barHeight - 2);
			String text = (session.wasLastGameWon() ? "Rift sealed" : "Rift closed")
				+ " - " + session.getFinalElementalEnergy() + "E / "
				+ session.getFinalCatalyticEnergy() + "C";
			shadowText(g, text, (width - fm.stringWidth(text)) / 2,
				baseline(g, y, barHeight), TEXT);
			return;
		}

		// caption row: phase label left, clock right (clock optional)
		shadowText(g, phase == GamePhase.MINING_PHASE ? "Mining" : "Crafting", 2, capBase, TEXT);
		if (config.showGameTimer())
		{
			Optional<String> clock = session.elapsedSinceRiftActive(now)
				.map(d -> mmss(d.getSeconds()));
			boolean observedOnly = false;
			if (!clock.isPresent())
			{
				clock = session.observedCraftingElapsed(now)
					.map(d -> "+" + mmss(d.getSeconds()));
				observedOnly = true;
			}
			if (clock.isPresent())
			{
				shadowText(g, clock.get(), width - fm.stringWidth(clock.get()) - 2, capBase,
					observedOnly ? TEXT_DIM : TEXT_YELLOW);
			}
		}

		// Camera-with-deadzone timeline: the cursor moves left-to-right through a stationary
		// timeline until it reaches the pin fraction, then stays pinned while the timeline
		// scrolls past it. Constant scale — never rescales.
		double pxPerSec = innerW / GotrConstants.TIMELINE_WINDOW_SECONDS;
		long pinMs = (long) (GotrConstants.TIMELINE_CURSOR_FRACTION
			* GotrConstants.TIMELINE_WINDOW_SECONDS * 1000);
		Optional<Instant> roundStart = session.getRiftActiveAt();
		Instant viewportStart = now.minusMillis(pinMs);
		if (roundStart.isPresent() && roundStart.get().isAfter(viewportStart))
		{
			viewportStart = roundStart.get();
		}
		int cursorX = xOf(now, viewportStart, pxPerSec);
		int base = baseline(g, y, barHeight);

		if (roundStart.isPresent())
		{
			int mineStartX = xOf(roundStart.get(), viewportStart, pxPerSec);
			int mineEndX = xOf(roundStart.get().plusSeconds(GotrConstants.MINING_PHASE_SECONDS),
				viewportStart, pxPerSec);
			// The whole mining section is always visible (dim); the elapsed part (behind the
			// cursor) is bright — so the fill advances left-to-right within the section.
			fillSpan(g, y, mineStartX, Math.min(cursorX, mineEndX), innerW, MINE_DONE);
			fillSpan(g, y, Math.max(cursorX, mineStartX), mineEndX, innerW, MINE_TODO);
			// crafting trail behind the cursor
			fillSpan(g, y, mineEndX, cursorX, innerW, TRAIL_FILL);
			if (mineEndX >= 1 && mineEndX <= innerW)
			{
				g.setColor(BORDER);
				g.fillRect(mineEndX, y + 1, 1, barHeight - 2);
			}
		}
		else if (phase == GamePhase.RIFT_ACTIVE)
		{
			fillSpan(g, y, 1, cursorX, innerW, TRAIL_FILL);
		}

		// portal marks (drift with the timeline; re-anchor only on real spawns)
		List<PortalMark> marks = session.portalMarks(now);
		Integer firstFutureX = null;
		int windowHalfPx = (int) (GotrConstants.PORTAL_ESTIMATE_TOLERANCE_SECONDS * pxPerSec);
		for (PortalMark mark : marks)
		{
			int x = xOf(mark.time, viewportStart, pxPerSec);
			int xEnd = xOf(mark.endTime, viewportStart, pxPerSec);
			switch (mark.state)
			{
				case PAST:
					// a real section spanning the portal's actual open duration
					if (config.showPortalMarkers())
					{
						fillSpan(g, y, x, xEnd, innerW, PORTAL_PAST);
					}
					break;
				case ACTIVE:
				{
					// solid yellow section from the real spawn to the real close
					fillSpan(g, y, x, xEnd, innerW, PORTAL_ACTIVE);
					String live = "Portal "
						+ (mark.secondsRemaining >= 0 ? mmss(mark.secondsRemaining) : "");
					shadowText(g, live,
						Math.min(Math.max(xEnd, 1) + 5, width - fm.stringWidth(live) - 4),
						base, PORTAL_TEXT);
					break;
				}
				case FUTURE:
					// transparent guess window: spawn tolerance plus the portal's duration
					if (config.showPortalMarkers() && xEnd + windowHalfPx >= 1
						&& x - windowHalfPx <= innerW)
					{
						int x1 = Math.max(1, x - windowHalfPx);
						int x2 = Math.min(innerW, xEnd + windowHalfPx);
						g.setColor(PORTAL_GUESS);
						g.fillRect(x1, y + 1, Math.max(2, x2 - x1), barHeight - 2);
						g.setColor(PORTAL_GUESS_EDGE);
						g.drawLine(x1, y + 1, x1, y + barHeight - 2);
						g.drawLine(x2, y + 1, x2, y + barHeight - 2);
						if (firstFutureX == null)
						{
							firstFutureX = x2;
						}
					}
					break;
			}
		}

		// the pinned "now" cursor
		g.setColor(CURSOR_SHADOW);
		g.fillRect(cursorX - 1, y, 3, barHeight);
		g.setColor(TEXT);
		g.fillRect(cursorX, y, 1, barHeight);

		// in-bar texts
		if (phase == GamePhase.MINING_PHASE)
		{
			String countdown = session.miningSecondsRemaining(now)
				.map(s -> "altars open " + mmss(s)).orElse("");
			shadowText(g, countdown, cursorX + 7, base, TEXT_YELLOW);
		}
		else if (!session.isPortalOpen())
		{
			Optional<Long> next = session.secondsToNextPortal(now);
			if (next.isPresent() && config.showPortalMarkers())
			{
				String text = "~" + mmss(next.get());
				int tx = firstFutureX != null
					? Math.min(firstFutureX + 4, width - fm.stringWidth(text) - 4)
					: cursorX + 7;
				shadowText(g, text, tx, base, PORTAL_TEXT);
			}
			else if (marks.isEmpty())
			{
				// mid-join with no anchor yet: show we're alive and waiting
				shadowText(g, "watching for portal...", cursorX + 7, base, pulse(PORTAL_TEXT));
			}
		}
	}

	/** Maps an absolute instant to a bar x within the current viewport. */
	private int xOf(Instant t, Instant viewportStart, double pxPerSec)
	{
		double dt = (t.toEpochMilli() - viewportStart.toEpochMilli()) / 1000.0;
		return 1 + (int) Math.round(dt * pxPerSec);
	}

	/** Fills a horizontal section of the bar, clipped to the bar's interior. */
	private void fillSpan(Graphics2D g, int barY, int fromX, int toX, int innerW, Color color)
	{
		int x1 = Math.max(1, fromX);
		int x2 = Math.min(innerW + 1, toX);
		if (x2 > x1)
		{
			g.setColor(color);
			g.fillRect(x1, barY + 1, x2 - x1, barHeight - 2);
		}
	}

	// ---- goal sub-bar ----------------------------------------------------------------------

	private boolean hasGoalSubBar(GotrSession session, GamePhase phase)
	{
		if (phase == GamePhase.MINING_PHASE)
		{
			return session.getFragmentGoal() > 0;
		}
		return session.hasPointsGoal();
	}

	private void renderGoalSubBar(Graphics2D g, GotrSession session, GamePhase phase,
		int width, int y)
	{
		frame(g, 0, y, width, subHeight);
		int innerW = width - 2;
		int base = baseline(g, y, subHeight);
		FontMetrics fm = g.getFontMetrics();

		if (phase == GamePhase.MINING_PHASE)
		{
			drawGoalFill(g, 1, y, innerW, session.getFragmentCount(),
				session.getFragmentGoal(), session.fragmentGoalState());
			shadowText(g, "Fragments", 6, base, TEXT);
			String v = session.getFragmentCount() + " / " + session.getFragmentGoal();
			shadowText(g, v, width - fm.stringWidth(v) - 6, base, TEXT);
			return;
		}

		if (session.getPointsMetric() == PointsMetric.BOTH_SPLIT)
		{
			// each half tracks its own goal (they can differ; 0 disables one side)
			int half = innerW / 2;
			drawGoalFill(g, 1, y, half - 1, session.getElementalEnergy(),
				session.getElementalPointsGoal(), session.splitElementalGoalState());
			drawGoalFill(g, half + 2, y, innerW - half - 2, session.getCatalyticEnergy(),
				session.getCatalyticPointsGoal(), session.splitCatalyticGoalState());
			g.setColor(BORDER);
			g.fillRect(half, y + 1, 2, subHeight - 2);
			shadowText(g, goalText("E", session.getElementalEnergy(),
				session.getElementalPointsGoal()), 6, base, TEXT);
			String c = goalText("C", session.getCatalyticEnergy(),
				session.getCatalyticPointsGoal());
			shadowText(g, c, width - fm.stringWidth(c) - 6, base, TEXT);
			return;
		}

		drawGoalFill(g, 1, y, innerW, session.pointsValue(), session.activePointsGoal(),
			session.pointsGoalState());
		String label;
		switch (session.getPointsMetric())
		{
			case ELEMENTAL:
				label = "Elemental";
				break;
			case CATALYTIC:
				label = "Catalytic";
				break;
			default:
				label = "Points";
		}
		shadowText(g, label, 6, base, TEXT);
		String v = session.pointsValue() + " / " + session.activePointsGoal();
		shadowText(g, v, width - fm.stringWidth(v) - 6, base, TEXT);
	}

	/** "E 161/200", or just "E 161" when that side's goal is disabled. */
	private String goalText(String prefix, int value, int goal)
	{
		return goal > 0 ? prefix + " " + value + "/" + goal : prefix + " " + value;
	}

	private void drawGoalFill(Graphics2D g, int x, int y, int w, int value, int goal,
		GoalState state)
	{
		if (state == GoalState.DISABLED || goal <= 0)
		{
			return;
		}
		double frac = Math.min(1.0, (double) value / (double) goal);
		int fillW = (int) (w * frac);
		if (fillW <= 0)
		{
			return;
		}
		Color c = state == GoalState.MET ? config.goalMetColor() : config.belowGoalColor();
		g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 115));
		g.fillRect(x, y + 1, fillW, subHeight - 2);
	}

	// ---- native-style drawing helpers ------------------------------------------------------

	private void frame(Graphics2D g, int x, int y, int w, int h)
	{
		g.setColor(BACKGROUND);
		g.fillRect(x, y, w, h);
		g.setColor(BORDER);
		g.drawRect(x, y, w - 1, h - 1);
	}

	private void shadowText(Graphics2D g, String text, int x, int y, Color color)
	{
		if (text.isEmpty())
		{
			return;
		}
		g.setColor(new Color(0, 0, 0, color.getAlpha()));
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Gentle alpha pulse for "alive but waiting" texts. */
	private Color pulse(Color c)
	{
		double s = (Math.sin(System.currentTimeMillis() / 400.0) + 1) / 2;
		int alpha = 130 + (int) (s * 125);
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	private int baseline(Graphics2D g, int y, int h)
	{
		// center the full line box (ascent+descent+leading); the +ascent-descent shortcut
		// ignores leading and sits visibly too low in the short bars
		FontMetrics fm = g.getFontMetrics();
		return y + (h - fm.getHeight()) / 2 + fm.getAscent();
	}

	private String mmss(long seconds)
	{
		return String.format("%d:%02d", seconds / 60, seconds % 60);
	}
}

package com.gotrprogressbar;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Dev launcher: starts a full RuneLite client with this plugin loaded.
 * Run via {@code gradlew.bat run} (passes --developer-mode --debug).
 */
public class GotrProgressBarPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GotrProgressBarPlugin.class);
		RuneLite.main(args);
	}
}

package com.gotrprogressbar;

import com.gotrprogressbar.model.GamePhase;
import com.gotrprogressbar.model.GoalState;
import com.gotrprogressbar.model.GotrSession;
import com.gotrprogressbar.model.HudSnapshot;
import com.gotrprogressbar.model.PointsMetric;
import com.gotrprogressbar.model.PortalMark;
import java.time.Instant;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Scenario values mirror live HUD logs from 2026-07-13: during mining, power sits at exactly
 * max/10 with rune indexes 0 and guardianTicks counting down ~200; crafting has rune
 * indexes > 0; between rounds power is 0 (guardianTicks holds garbage negatives).
 */
public class GotrSessionTest
{
	private static final Instant T0 = Instant.ofEpochSecond(1_000_000);
	private static final int MAX_POWER = 101800;

	private GotrSession session;

	@Before
	public void setUp()
	{
		session = new GotrSession();
		session.setInMinigame(true);
	}

	private static HudSnapshot crafting(int elem, int cata, int power,
		int portalLocation, int portalTicks)
	{
		return new HudSnapshot(elem, cata, power, MAX_POWER, portalLocation,
			1, 1, 5, 10, 100, portalTicks);
	}

	/** Crafting snapshot at the given power fraction (e.g. 0.28 = 28%). */
	private static HudSnapshot craftingAtPower(double fraction)
	{
		return crafting(50, 50, (int) (MAX_POWER * fraction), -1, -1);
	}

	private static HudSnapshot mining(int guardianTicks)
	{
		return new HudSnapshot(0, 0, MAX_POWER / 10, MAX_POWER, 0,
			0, 0, 10, 10, guardianTicks, -1);
	}

	private static HudSnapshot idle()
	{
		return new HudSnapshot(0, 0, 0, MAX_POWER, 0, 0, 0, 10, 10, -779337, -1);
	}

	private static HudSnapshot won(int elem, int cata)
	{
		return new HudSnapshot(elem, cata, MAX_POWER, MAX_POWER, 0, 0, 0, 10, 10, 0, -1);
	}

	private static Instant at(long secondsAfterT0)
	{
		return T0.plusSeconds(secondsAfterT0);
	}

	@Test
	public void entersWaitingWhenInMinigame()
	{
		assertEquals(GamePhase.WAITING_FOR_GAME, session.getPhase());
	}

	@Test
	public void fullHappyPath()
	{
		// between rounds: idle HUD, then the chat countdown to round start
		session.onHudUpdate(idle(), at(0));
		assertEquals(GamePhase.WAITING_FOR_GAME, session.getPhase());
		session.onChatMessage(GotrConstants.CHAT_START_30S, at(0));
		assertEquals(GamePhase.WAITING_FOR_GAME, session.getPhase());
		assertEquals(Long.valueOf(30), session.secondsToGameStart(at(0)).get());
		assertEquals(0.5, session.waitingFillFraction(at(15)).get(), 0.01);
		session.onChatMessage(GotrConstants.CHAT_START_10S, at(20));
		assertEquals(Long.valueOf(10), session.secondsToGameStart(at(20)).get());

		// round starts -> mining phase with the nominal 120 s window until HUD refines it
		session.onChatMessage(GotrConstants.CHAT_RIFT_ACTIVE, at(30));
		assertEquals(GamePhase.MINING_PHASE, session.getPhase());
		assertEquals(Long.valueOf(120), session.miningSecondsRemaining(at(30)).get());

		// HUD countdown takes over (178 ticks = 106.8 s)
		session.onHudUpdate(mining(178), at(44));
		assertEquals(Long.valueOf(106), session.miningSecondsRemaining(at(44)).get());

		// altars open -> crafting
		session.onHudUpdate(craftingAtPower(0.11), at(150));
		assertEquals(GamePhase.RIFT_ACTIVE, session.getPhase());
		assertEquals(120, session.elapsedSinceRiftActive(at(150)).get().getSeconds());

		// win: power reaches max
		session.onHudUpdate(won(190, 210), at(400));
		assertEquals(GamePhase.GAME_END, session.getPhase());
		assertTrue(session.wasLastGameWon());
		assertEquals(190, session.getFinalElementalEnergy());
		assertEquals(210, session.getFinalCatalyticEnergy());

		// summary holds, then returns to waiting
		session.tick(at(405));
		assertEquals(GamePhase.GAME_END, session.getPhase());
		session.tick(at(400 + GotrConstants.GAME_END_SUMMARY_SECONDS + 1));
		assertEquals(GamePhase.WAITING_FOR_GAME, session.getPhase());
	}

	@Test
	public void portalMarksAreAnchoredToRealSpawns()
	{
		session.onChatMessage(GotrConstants.CHAT_RIFT_ACTIVE, at(0));
		session.onHudUpdate(mining(178), at(14));

		// futures already laid out during mining: t0+160, t0+300, ...
		List<PortalMark> marks = session.portalMarks(at(30));
		assertFalse(marks.isEmpty());
		assertEquals(PortalMark.State.FUTURE, marks.get(0).state);
		assertEquals(at(GotrConstants.FIRST_PORTAL_DELAY_SECONDS), marks.get(0).time);
		assertEquals(at(GotrConstants.FIRST_PORTAL_DELAY_SECONDS
			+ GotrConstants.PORTAL_CYCLE_SECONDS), marks.get(1).time);

		// fresh spawn at t=165 (full 44-tick lifetime -> no backdating):
		// ACTIVE mark at its real time, futures re-anchored off it
		session.onHudUpdate(craftingAtPower(0.12), at(130));
		session.onHudUpdate(crafting(20, 20, 15000, 3, GotrConstants.PORTAL_LIFETIME_TICKS),
			at(165));
		marks = session.portalMarks(at(166));
		assertEquals(PortalMark.State.ACTIVE, marks.get(0).state);
		assertEquals(at(165), marks.get(0).time);
		assertEquals(PortalMark.State.FUTURE, marks.get(1).state);
		assertEquals(at(165 + GotrConstants.PORTAL_CYCLE_SECONDS), marks.get(1).time);

		// despawn -> PAST tick stays at t=165
		session.onHudUpdate(craftingAtPower(0.2), at(190));
		marks = session.portalMarks(at(191));
		assertEquals(PortalMark.State.PAST, marks.get(0).state);
		assertEquals(at(165), marks.get(0).time);
		assertEquals(Long.valueOf(165 + GotrConstants.PORTAL_CYCLE_SECONDS - 191),
			session.secondsToNextPortal(at(191)).get());
	}

	@Test
	public void portalSeenMidLifeIsBackdatedToItsRealSpawn()
	{
		// join mid-craft while a portal is already open with 20 of 44 ticks left:
		// it spawned (44-20)*0.6 = 14.4 s ago
		session.onHudUpdate(crafting(50, 50, 40000, 3, 20), at(100));
		List<PortalMark> marks = session.portalMarks(at(100));
		assertEquals(PortalMark.State.ACTIVE, marks.get(0).state);
		assertEquals(T0.plusMillis(100_000 - 14_400), marks.get(0).time);
		// the next window anchors off the TRUE spawn, not the moment we noticed it
		assertEquals(T0.plusMillis(100_000 - 14_400)
			.plusSeconds(GotrConstants.PORTAL_CYCLE_SECONDS), marks.get(1).time);
	}

	@Test
	public void miningPhaseDetectedFromHudWithoutChat()
	{
		// joined mid-mining: no chat anchor, HUD alone drives the phase
		session.onHudUpdate(mining(150), at(0));
		assertEquals(GamePhase.MINING_PHASE, session.getPhase());
		assertEquals(Long.valueOf(90), session.miningSecondsRemaining(at(0)).get());
		// round start derived from the nominal window -> the timeline has an anchor
		assertTrue(session.getRiftActiveAt().isPresent());
	}

	@Test
	public void midJoinMiningNeverPlacesRoundStartInFuture()
	{
		// A countdown longer than the nominal mining length must clamp the round start to
		// "now" rather than derive a future instant (which rendered the bar backwards).
		session.onHudUpdate(mining(GotrConstants.MINING_PHASE_TICKS_MAX), at(0));
		assertEquals(GamePhase.MINING_PHASE, session.getPhase());
		Instant start = session.getRiftActiveAt().get();
		assertFalse("round start must not be in the future", start.isAfter(at(0)));
		// elapsed is therefore never negative
		assertTrue(session.elapsedSinceRiftActive(at(0)).get().toMillis() >= 0);
	}

	@Test
	public void midCraftJoinLandsInRiftActive()
	{
		session.onHudUpdate(craftingAtPower(0.4), at(0));
		assertEquals(GamePhase.RIFT_ACTIVE, session.getPhase());
		// round start unknown: no clock, no marks until the first observed portal
		assertFalse(session.getRiftActiveAt().isPresent());
		assertFalse(session.elapsedSinceRiftActive(at(1)).isPresent());
		assertTrue(session.portalMarks(at(1)).isEmpty());

		session.onHudUpdate(crafting(80, 90, 45000, 3, 41), at(20));
		assertTrue(session.isPortalOpen());
		session.onHudUpdate(craftingAtPower(0.5), at(45));
		assertFalse(session.isPortalOpen());
		List<PortalMark> marks = session.portalMarks(at(50));
		assertEquals(PortalMark.State.PAST, marks.get(0).state);
		assertEquals(PortalMark.State.FUTURE, marks.get(1).state);
	}

	@Test
	public void portalCountdownComesFromHudTicks()
	{
		session.onChatMessage(GotrConstants.CHAT_RIFT_ACTIVE, at(0));
		session.onHudUpdate(crafting(10, 10, 30000, 4, 40), at(160));
		// 40 ticks * 600ms = 24s
		assertEquals(Long.valueOf(24), session.portalSecondsRemaining(at(160)).get());
		assertEquals(Long.valueOf(19), session.portalSecondsRemaining(at(165)).get());
	}

	@Test
	public void gameLossEndsGame()
	{
		session.onChatMessage(GotrConstants.CHAT_RIFT_ACTIVE, at(0));
		session.onHudUpdate(craftingAtPower(0.3), at(130));
		assertEquals(GamePhase.RIFT_ACTIVE, session.getPhase());
		session.onHudUpdate(idle(), at(200));
		assertEquals(GamePhase.GAME_END, session.getPhase());
		assertFalse(session.wasLastGameWon());
	}

	@Test
	public void staleStartCountdownIsDropped()
	{
		session.onChatMessage(GotrConstants.CHAT_START_30S, at(0));
		assertEquals(GamePhase.WAITING_FOR_GAME, session.getPhase());
		assertTrue(session.secondsToGameStart(at(5)).isPresent());
		session.tick(at(41));
		assertFalse(session.secondsToGameStart(at(41)).isPresent());
	}

	@Test
	public void portalsExtendMessageAnchorsNextStart()
	{
		session.onChatMessage(GotrConstants.CHAT_PORTALS_EXTEND, at(0));
		assertEquals(GamePhase.WAITING_FOR_GAME, session.getPhase());
		assertEquals(Long.valueOf(60), session.secondsToGameStart(at(0)).get());
	}

	@Test
	public void leavingAreaResetsToOutside()
	{
		session.onChatMessage(GotrConstants.CHAT_RIFT_ACTIVE, at(0));
		session.setInMinigame(false);
		assertEquals(GamePhase.OUTSIDE, session.getPhase());
		session.setInMinigame(true);
		assertEquals(GamePhase.WAITING_FOR_GAME, session.getPhase());
		assertFalse(session.elapsedSinceRiftActive(at(10)).isPresent());
		assertFalse(session.miningSecondsRemaining(at(10)).isPresent());
		assertTrue(session.portalMarks(at(10)).isEmpty());
	}

	@Test
	public void fragmentGoal()
	{
		session.setGoals(120, PointsMetric.COMBINED, 300, 150, 150);
		session.setFragmentCount(84);
		assertEquals(GoalState.BELOW, session.fragmentGoalState());
		session.setFragmentCount(120);
		assertEquals(GoalState.MET, session.fragmentGoalState());
		session.setGoals(0, PointsMetric.COMBINED, 300, 150, 150);
		assertEquals(GoalState.DISABLED, session.fragmentGoalState());
	}

	@Test
	public void pointsMetrics()
	{
		session.onHudUpdate(crafting(160, 90, 30000, -1, -1), at(0));

		session.setGoals(120, PointsMetric.COMBINED, 300, 150, 150);
		assertEquals(250, session.pointsValue());
		assertEquals(300, session.activePointsGoal());
		assertEquals(GoalState.BELOW, session.pointsGoalState());
		assertTrue(session.hasPointsGoal());

		session.setGoals(120, PointsMetric.ELEMENTAL, 300, 150, 150);
		assertEquals(160, session.pointsValue());
		assertEquals(150, session.activePointsGoal());
		assertEquals(GoalState.MET, session.pointsGoalState());

		session.setGoals(120, PointsMetric.CATALYTIC, 300, 150, 150);
		assertEquals(90, session.pointsValue());
		assertEquals(GoalState.BELOW, session.pointsGoalState());

		// split: each side has its OWN goal (200 elemental vs 80 catalytic here)
		session.setGoals(120, PointsMetric.BOTH_SPLIT, 300, 200, 80);
		assertEquals(GoalState.BELOW, session.splitElementalGoalState());
		assertEquals(GoalState.MET, session.splitCatalyticGoalState());
		assertTrue(session.hasPointsGoal());

		// split with one side disabled still shows the other
		session.setGoals(120, PointsMetric.BOTH_SPLIT, 300, 0, 80);
		assertEquals(GoalState.DISABLED, session.splitElementalGoalState());
		assertTrue(session.hasPointsGoal());

		session.setGoals(120, PointsMetric.COMBINED, 0, 150, 150);
		assertEquals(GoalState.DISABLED, session.pointsGoalState());
		assertFalse(session.hasPointsGoal());
	}

	@Test
	public void malformedScriptArgsAreRejected()
	{
		assertEquals(null, HudSnapshot.fromArgs(null));
		assertEquals(null, HudSnapshot.fromArgs(new Object[]{5980, 1, 2}));
		Object[] bad = new Object[GotrConstants.HUD_SCRIPT_ARG_COUNT];
		bad[0] = 5980;
		for (int i = 1; i < bad.length; i++)
		{
			bad[i] = i == 5 ? "not an int" : 1;
		}
		assertEquals(null, HudSnapshot.fromArgs(bad));
	}

	@Test
	public void hudStateClassification()
	{
		assertTrue(mining(178).isMiningPhase());
		assertFalse(mining(178).isCrafting());
		assertFalse(idle().isMiningPhase());
		assertTrue(idle().isIdle());
		assertTrue(craftingAtPower(0.2).isCrafting());
		assertFalse(craftingAtPower(0.2).isMiningPhase());
		assertTrue(won(10, 10).isGameWon());
		// garbage negative ticks between rounds must never read as mining
		HudSnapshot garbage = new HudSnapshot(0, 0, MAX_POWER / 10, MAX_POWER, 0,
			0, 0, 10, 10, -779337, -1);
		assertFalse(garbage.isMiningPhase());
	}

}

package com.gotrprogressbar;

import com.gotrprogressbar.model.PortalPrediction;
import java.time.Instant;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class PortalPredictionTest
{
	private static final Instant T0 = Instant.ofEpochSecond(2_000_000);

	private PortalPrediction prediction;

	@Before
	public void setUp()
	{
		prediction = new PortalPrediction();
	}

	private static Instant at(long secondsAfterT0)
	{
		return T0.plusSeconds(secondsAfterT0);
	}

	@Test
	public void noEstimateWithoutAnchor()
	{
		assertFalse(prediction.nextWindow(at(0)).isPresent());
	}

	@Test
	public void firstWindowCentersOnFirstPortalDelay()
	{
		prediction.anchor(at(0));
		PortalPrediction.Window w = prediction.nextWindow(at(10)).get();
		assertEquals(at(GotrConstants.FIRST_PORTAL_DELAY_SECONDS
			- GotrConstants.PORTAL_ESTIMATE_TOLERANCE_SECONDS), w.start);
		assertEquals(at(GotrConstants.FIRST_PORTAL_DELAY_SECONDS
			+ GotrConstants.PORTAL_ESTIMATE_TOLERANCE_SECONDS), w.end);
	}

	@Test
	public void observedSpawnReanchorsTheCycle()
	{
		prediction.anchor(at(0));
		prediction.onPortalSpawn(at(165));
		// suppressed while open
		assertFalse(prediction.nextWindow(at(170)).isPresent());
		assertTrue(prediction.isPortalOpen());

		prediction.onPortalDespawn(at(190));
		PortalPrediction.Window w = prediction.nextWindow(at(200)).get();
		assertEquals(at(165 + GotrConstants.PORTAL_CYCLE_SECONDS
			- GotrConstants.PORTAL_ESTIMATE_TOLERANCE_SECONDS), w.start);
		assertEquals(at(165 + GotrConstants.PORTAL_CYCLE_SECONDS
			+ GotrConstants.PORTAL_ESTIMATE_TOLERANCE_SECONDS), w.end);
	}

	@Test
	public void staleWindowIsDropped()
	{
		prediction.anchor(at(0));
		long pastWindow = GotrConstants.FIRST_PORTAL_DELAY_SECONDS
			+ GotrConstants.PORTAL_ESTIMATE_TOLERANCE_SECONDS + 1;
		assertFalse(prediction.nextWindow(at(pastWindow)).isPresent());
	}

	@Test
	public void secondsToNextEstimateCountsDown()
	{
		prediction.anchor(at(0));
		assertEquals(Long.valueOf(GotrConstants.FIRST_PORTAL_DELAY_SECONDS - 100),
			prediction.secondsToNextEstimate(at(100)).get());
	}

	@Test
	public void historyIsKeptForTheTimeStrip()
	{
		prediction.anchor(at(0));
		prediction.onPortalSpawn(at(160));
		prediction.onPortalDespawn(at(185));
		prediction.onPortalSpawn(at(300));
		assertEquals(2, prediction.getSpawnHistory().size());
		assertEquals(at(160), prediction.getSpawnHistory().get(0));
	}

	@Test
	public void resetClearsEverything()
	{
		prediction.anchor(at(0));
		prediction.onPortalSpawn(at(160));
		prediction.reset();
		assertFalse(prediction.nextWindow(at(161)).isPresent());
		assertEquals(0, prediction.getSpawnHistory().size());
		assertFalse(prediction.isPortalOpen());
	}
}
